    "🌱 Court the Freshman Class": "🌱 Convencer a los recién llegados",
    "The newest members are the most movable. And the most afraid of a primary.": "Los nuevos miembros son flexibles, pero temen las primarias.",
    "A closed-door session with the freshman class. Twenty votes, and one very sincere hug.": "Reunión privada con los nuevos. Veinte votos y un abrazo sincero.",
    "🔐 The Closed-Door Briefing": "🔐 Informe a puerta cerrada",
    "Show the holdouts what you actually have. Nothing leaks. That is the point.": "Enseña las pruebas a los indecisos. Sin filtraciones, deliberadamente.",
    "Ninety minutes, no phones, no staff. Twenty-six votes and not a single leak.": "90 minutos sin teléfonos ni personal. 26 votos, ninguna filtración.",
    "🚪 Retire a Ranking Member": "🚪 Retirar al miembro de mayor rango",
    "Remove an obstacle from the committee. Effective, and it will be remembered.": "Elimina un obstáculo de la comisión. Eficaz, pero deja huella.",
    "The ranking member steps down. Thirty votes unlock. Six points of goodwill evaporate.": "El miembro dimite. Se liberan 30 votos y se pierden seis puntos de apoyo.",
    "🤝 Cross-Party Coalition": "🤝 Coalición entre partidos",
