    "Requires Evidence ≥ 85. The one document nobody has seen yet.": "Requiere Pruebas ≥ 85. El documento que nadie ha visto.",
    "Requires Evidence ≥ 85": "Requiere Pruebas ≥ 85",
    "The document is entered into the record at 9:41 PM. The chamber goes silent. Six votes move overnight.": "El documento entra a las 21:41. Silencio en la sala. Seis votos cambian esa noche.",
    "🏛️ The Constitutional Argument": "🏛️ Argumento constitucional",
    "Remind the Senate what \"high crimes and misdemeanors\" has always meant.": "Recuerda al Senado el sentido de «delitos graves y faltas».",
    "Your closing argument quotes the 1974 committee report. Two senators take notes.": "Citas el informe de 1974. Dos senadores toman notas.",
    "📝 Trial Manager's Closing": "📝 Alegato final de la acusación",
    "The last word on the record. Persuasive if the case is already strong.": "La última palabra. Persuasiva si el expediente ya es sólido.",
    "Ninety minutes, no notes. The chamber is quiet for the first time in six weeks.": "90 minutos sin notas. La sala calla por primera vez en seis semanas.",
    "📰 Hometown Editorial Blitz": "📰 Ofensiva editorial local",
    "Buy the opinion pages back home. Cheaper than a rally and harder to ignore.": "Gana las páginas de opinión locales. Más barato que un mitin, difícil de ignorar.",
    "Fourteen editorial boards endorse conviction in a single week. Two senators stop taking questions.": "14 editoriales respaldan la condena en una semana. Dos senadores evitan preguntas.",
    "🔎 Senator-by-Senator Audit": "🔎 Análisis de cada senador",
    "A full workup on every undecided vote. Expensive, methodical, effective.": "Investiga a cada indeciso. Costoso, metódico, eficaz.",
    "The audit identifies four soft votes and two that will never move. You stop wasting time on the two.": "Detectas cuatro votos flexibles y dos inamovibles. Dejas de perder tiempo con estos últimos.",
    "⚖️ The Recusal Motion": "⚖️ Moción de recusación",
    "Move to recuse a presiding officer. All upside if it lands, all cost if it does not.": "Pide apartar al presidente del juicio. Gran beneficio o coste sin retorno.",
    "The motion is granted. Ten votes shift the moment the gavel comes down.": "Se acepta la moción. Diez votos cambian al caer el mazo.",
    "The motion fails on a party-line vote. Six points of public support go with it.": "La moción fracasa por voto partidista. Pierdes seis puntos de apoyo.",
    "🎙️ Prime-Time Witness Recall": "🎙️ Volver a citar al testigo en TV",
    "Bring the best witness back for the cameras. The country is watching again.": "Trae de nuevo al mejor testigo. El país vuelve a mirar.",
    "The witness returns, and this time the networks carry it live. Eleven votes and six points of support.": "El testigo regresa en directo. Once votos y seis puntos de apoyo.",
    "🤐 Negotiate the Resignation": "🤐 Negociar la dimisión",
    "Skip the trial. Offer an exit. It works — and the record goes with him.": "Ofrece una salida sin juicio. Funciona, pero sacrifica pruebas.",
    "A resignation is negotiated in principle. Fourteen votes secure. Ten evidentiary items are sealed forever.": "Acuerdo de dimisión en principio. 14 votos asegurados; diez pruebas selladas para siempre.",
    "☢️ The Constitutional Nuclear Option": "☢️ Opción nuclear constitucional",
    "Threaten the institution itself. It moves votes and costs you the moral high ground.": "Amenaza a la institución. Ganas votos, pierdes autoridad moral.",
    "The threat is made on the record. Nine votes move. Five points of goodwill do not come back.": "La amenaza queda en acta. Nueve votos ganados; cinco puntos de apoyo perdidos.",
    "🎲 Court-Packing Leverage": "🎲 Presión con ampliar el tribunal",
    "Remind a few senators what happens if this drags on. Blunt, and it sometimes backfires.": "Recuerda a los senadores las consecuencias de alargar el caso. Puede salir mal.",
    "The leverage works for seven votes — and costs you six capital in favors called in.": "La presión gana siete votos y cuesta seis de capital en favores.",
    "The leverage works. Seven votes move, and nobody puts it in writing.": "La presión funciona. Siete votos, sin nada por escrito.",
    "🕊️ The Immunity Offer": "🕊️ Oferta de inmunidad",
    "Trade a prosecution for a conviction. The vote count goes up; the record gets thinner.": "Renuncia a procesar a alguien para conseguir una condena. Más votos, menos pruebas.",
    "Immunity is offered and accepted. Twelve votes secure. Six evidentiary items are withdrawn.": "La inmunidad se acepta. Doce votos asegurados, seis pruebas retiradas.",
    "A second whistleblower comes forward with corroborating documents.": "Un segundo denunciante aporta documentos que corroboran el caso.",
    "A key witness recants under pressure. Two months of work evaporate.": "Un testigo clave se retracta bajo presión. Dos meses de trabajo se esfuman.",
    "A viral town hall clip changes the conversation for a week.": "Un vídeo viral de una reunión vecinal cambia el debate durante una semana.",
    "The administration's counter-programming dominates the news cycle.": "La contraofensiva mediática del Gobierno domina las noticias.",
    "A procedural floor fight burns a week of the calendar and a lot of goodwill.": "Una disputa de procedimiento consume una semana y mucha buena voluntad.",
    "A leadership reshuffle hands you a friendlier Rules Committee.": "Un cambio de dirigentes te da una comisión de reglas más favorable.",
    "A swing senator tells a reporter, on the record, \"I'm listening.\"": "Un senador indeciso dice a la prensa: «Estoy escuchando».",
    "A late-night monologue puts the scandal back on the front page.": "Un monólogo nocturno devuelve el escándalo a las portadas.",
    "A committee gaffe hands the defense a week of free messaging.": "Un error de la comisión regala a la defensa una semana de propaganda.",
    "the Marina Bay Contract": "el Contrato de Marina Bay",
    "the Offshore Ledger": "el Libro Contable Extraterritorial",
    "the Pardon-for-Pay Arrangement": "el Acuerdo de Indultos a Cambio de Dinero",
    "the Classified Basement": "el Sótano Clasificado",
    "the Hotel Emoluments Question": "la Cuestión de los Beneficios Hoteleros",
    "the Inaugural Committee Transfers": "las Transferencias del Comité de Investidura",
    "the Family Foundation Filing": "la Declaración de la Fundación Familiar",
    "the Midnight Regulatory Rollback": "la Derogación Regulatoria de Medianoche",
    "The hearing room is standing room only.": "La sala está tan llena que solo queda sitio de pie.",
    "Three networks cut away from regular programming.": "Tres cadenas interrumpen su programación.",
    "The press gallery is unusually quiet.": "La tribuna de prensa está extrañamente callada.",
    "Someone leaks the witness list at 11:58 PM.": "Alguien filtra la lista de testigos a las 23:58.",
    "A court clerk hands over a sealed envelope.": "Un secretario judicial entrega un sobre sellado.",
    "The ranking member calls it \"the paper trail of the century.\"": "El miembro de mayor rango lo llama «el rastro documental del siglo».",
    "A staffer wheels in a cart of bankers boxes.": "Un empleado entra con un carro de cajas de documentos.",
    "No dispatches yet": "Aún no hay noticias",
