    "You never assembled enough evidence to report articles out of committee. The term ended with the boxes still unopened.": "No reuniste pruebas suficientes para sacar los artículos de la comisión. El mandato acabó con las cajas sin abrir.",
    "The vote count stalled short of 218. The articles die on the calendar.": "El recuento no llegó a 218. Los artículos caducan al terminar el mandato.",
