    "The Senate votes to convict. The Chief Justice administers the oath of removal. You did not change anyone's mind in a single afternoon — you built a record, one document at a time, until the record became impossible to ignore.": "El Senado vota la condena. Se formaliza la destitución. No cambiaste todas las opiniones en una tarde: construiste un expediente, documento a documento, hasta hacerlo imposible de ignorar.",
    "Public support falls below the floor. Members start avoiding the cameras. The articles are tabled indefinitely, and the whole thing becomes a cautionary tale told at staff retreats.": "El apoyo público cae demasiado. Los miembros evitan las cámaras. Los artículos se aplazan indefinidamente y el caso se convierte en una advertencia para futuros equipos.",
