    "Success: {0}% · {1} +{2}–{3}": "Éxito: {0}% · {1} +{2}–{3}",
    "Support on success: {0} to {1}": "Apoyo si funciona: de {0} a {1}",
    "On failure: {0} −{1}–{2}; support −{3}–{4}.": "Si falla: {0} −{1}–{2}; apoyo −{3}–{4}.",
    "Evidence cost on success: {0}.": "Coste en pruebas si funciona: {0}.",
    "No affordable moves. Adjourn to rebuild capital; blowback can halve the recovery.": "No hay movimientos asequibles. Levanta la sesión para recuperar capital; una reacción puede reducirlo a la mitad.",
    "BLOWBACK — Political capital halved: {0} → {1} (rounded down).": "REACCIÓN ADVERSA — Capital político a la mitad: {0} → {1} (redondeado hacia abajo).",
    "Extended Toolkit unlocked: 56 moves per phase instead of 28.": "Herramientas ampliadas: 56 movimientos por fase en lugar de 28.",
    "A shorter term. Less public fatigue. 28 moves per phase.": "Mandato más corto. Menor fatiga pública. 28 movimientos por fase.",
    "A longer term. More public fatigue. 56 moves per phase, with lower success odds.": "Mandato más largo. Mayor fatiga pública. 56 movimientos por fase, con menos probabilidades de éxito.",
    "Adjourn skips unused days to recover capital. Every blowback halves your capital after recovery, rounded down.": "Levantar la sesión omite los días restantes para recuperar capital. Cada reacción adversa reduce a la mitad el capital tras la recuperación, redondeando hacia abajo.",
    "Every move can fail. Cards show success odds and rewards; stronger public support improves your odds.": "Cualquier movimiento puede fallar. Las cartas muestran probabilidades y recompensas; más apoyo mejora tus posibilidades.",
    "Public support shifts after every move and active-play day. Paused time does not affect it.": "El apoyo cambia tras cada movimiento y día de juego activo. El tiempo en pausa no influye."
