    "U.S. setting: this fictional game uses the U.S. House, Senate and impeachment process. Its rules simplify that system; they do not describe your country.": "미국 배경: 이 가상 게임은 미국 하원·상원과 탄핵 절차를 다룹니다. 규칙은 미국 제도를 단순화한 것이며 다른 나라의 제도를 설명하지 않습니다.",
