    "Campaign moves. Swipe, scroll, or use left and right arrow keys.": "행동 목록. 밀거나 스크롤하거나 좌우 방향키를 사용하세요.",
    "Move Options": "행동 선택",
    "Swipe or use the arrows · moves update with your campaign": "밀거나 화살표를 사용하세요 · 진행에 따라 행동이 바뀝니다",
    "Adjourn — Advance the Calendar": "산회 — 다음 달로",
    "Political fiction: every president, scandal, witness and senator is invented. The game simplifies U.S. constitutional procedures.": "정치적 허구: 대통령, 스캔들, 증인, 상원의원은 모두 가상입니다. 미국 헌법 절차를 단순화한 게임입니다.",
    "Call the House to Order": "하원 개회를 선언하세요",
    "Choose your calendar. Read the brief. You control when the clock starts.": "임기를 선택하고 규칙을 읽으세요. 시계는 직접 시작할 때 움직입니다.",
    "Choose your campaign": "캠페인 선택",
    "HARD": "어려움",
    "2 Years": "2년",
    "24 months · 240 session days": "24개월 · 회기 240일",
    "A shorter term. Less public fatigue. Seven moves per phase.": "짧은 임기, 적은 국민 피로도. 단계마다 행동 7개.",
    "Monthly: 20–26 capital · support −1 (+fatigue) · 65% blowback risk": "매달: 자본 +20~26 · 지지 −1(피로도 추가) · 역풍 확률 65%",
    "HARDER": "더 어려움",
