    "48 months · 480 session days": "48개월 · 회기 480일",
    "A longer term. More public fatigue. Fourteen moves per phase.": "긴 임기, 높은 국민 피로도. 단계마다 행동 14개.",
    "Monthly: 16–22 capital · support −2 (+fatigue) · evidence −2 after investigation · 80% blowback risk": "매달: 자본 +16~22 · 지지 −2(피로도 추가) · 조사 후 증거 −2 · 역풍 확률 80%",
    "Quickstart · Your path to a verdict": "빠른 시작 · 평결까지의 길",
    "Build 75 Evidence to bring articles to the House.": "증거 75점을 모아 탄핵안을 하원 본회의에 제출하세요.",
    "Win 218 House votes to impeach, then 67 Senate votes to convict and remove.": "하원 218표로 탄핵소추한 뒤 상원 67표로 유죄 결정과 파면을 이끌어내세요.",
    "Spend capital and days on moves. Every 12 seconds of active play also spends one day; 10 days make a month.": "행동에는 자본과 일수가 듭니다. 실제 플레이 12초마다 하루가 추가로 소모됩니다. 10일이 한 달입니다.",
    "Adjourn skips unused days. Each month restores capital but brings fatigue and a chance of blowback.": "산회하면 남은 날을 건너뜁니다. 매달 자본을 회복하지만 피로도와 역풍 위험이 생깁니다.",
    "Finish before the term ends. Keep support at 12% or higher at each monthly review. Pause or hide the tab to stop the clock.": "임기 안에 끝내세요. 매달 점검 때 지지율 12% 이상을 유지하세요. 일시정지하거나 탭을 숨기면 시계가 멈춥니다.",
    "Start the Session": "회기 시작",
    "Run It Back": "다시 하기",
    "A Political Simulation": "정치 시뮬레이션",
    "Build the case, count the votes, and beat the calendar in a fictional political strategy game.": "증거를 모으고 표를 확보하며 시간과 겨루는 가상의 정치 전략 게임입니다.",
    "Subpoena compliance produces {0} new documents. {1}": "소환장 이행으로 새 문서 {0}건을 확보했습니다. {1}",
    "A career official testifies for six hours. {0} new evidentiary items entered into the record.": "공무원이 6시간 증언합니다. 새 증거 {0}건이 기록됩니다.",
    "The judge rejects the blanket privilege claim and orders production. {0} new items land.": "판사가 포괄적 특권 주장을 기각합니다. 새 증거 {0}건을 확보합니다.",
    "The auditors find {0} irregularities. Nobody tweets about it, but it holds up in court.": "감사에서 부정 {0}건을 발견합니다. 화제는 아니지만 법정에서 통합니다.",
    "The Deputy AG is deposed for five hours. {0} new items, and one very long silence.": "법무부 부장관이 5시간 증언합니다. 증거 {0}건과 긴 침묵이 남습니다.",
    "{0} new items secured — but the contempt fight dominates the news and costs you five points.": "증거 {0}건 확보. 하지만 의회 모독 공방으로 지지 5점을 잃습니다.",
    "The Chief of Staff testifies for seven hours. {0} new evidentiary items.": "비서실장이 7시간 증언합니다. 증거 {0}건 추가.",
    "A second counsel is appointed. The {0} documents that follow are the best of the entire inquiry.": "두 번째 특별검사를 임명합니다. 핵심 문서 {0}건을 확보합니다.",
    "The outside accountant follows the money through three shell entities. {0} new items.": "외부 회계사가 유령회사 3곳의 돈을 추적합니다. 증거 {0}건 추가.",
    "Two foreign ministries comply. {0} new items, and a very good photograph of a courier van.": "외국 부처 두 곳이 협조합니다. 증거 {0}건과 멋진 배송차 사진을 얻습니다.",
    "A second whistleblower is secured and sequestered. {0} new items entered under seal.": "두 번째 내부고발자를 보호합니다. 봉인된 증거 {0}건 추가.",
    "The whip count moves by {0}. Three members who were \"undecided\" are no longer undecided.": "지지표가 {0}표 늘었습니다. 미정이던 의원 3명이 결심했습니다.",
    "You secure {0} more votes. One senator asks, twice, whether this is \"really worth it.\"": "{0}표 추가 확보. 한 상원의원이 두 번 묻습니다. “정말 가치가 있나요?”",
