    "No blowback this turn. The administration fails to land a counterattack.": "이번 턴에는 역풍이 없습니다. 행정부의 반격이 실패했습니다.",
    "You never assembled enough evidence to report articles out of committee. The term ended with the boxes still unopened.": "위원회에서 탄핵안을 제출할 만큼 증거를 모으지 못했습니다. 상자도 열지 못한 채 임기가 끝났습니다.",
    "The vote count stalled short of 218. The articles die on the calendar.": "표가 218에 못 미쳤습니다. 탄핵안이 기한 만료로 폐기됩니다.",
    "The Senate never reaches 67. The President is acquitted, declares victory, and fundraises off it.": "상원은 67표에 못 미쳤습니다. 대통령은 무죄를 선언받고 승리를 자축하며 모금합니다.",
    "THE TERM ENDS": "임기 종료",
    "THE CASE COLLAPSES": "사건 붕괴",
    "Extended Toolkit unlocked: 14 moves per phase instead of 7.": "확장 도구 해제: 단계마다 7개 대신 14개 행동.",
    "The calendar is live: 12 seconds of active play costs one session day. Moves also spend their listed days.": "시계가 흐릅니다. 플레이 12초마다 하루가 소모됩니다. 행동도 표시된 일수를 소모합니다.",
    "The House will come to order…": "개회를 선언합니다…",
    "Select a mode above to enable Start. The clock is stopped.": "모드를 선택하면 시작 버튼이 활성화됩니다. 시계는 멈춰 있습니다.",
    "The Senate votes to convict. The Chief Justice administers the oath of removal. You did not change anyone's mind in a single afternoon — you built a record, one document at a time, until the record became impossible to ignore.": "상원이 유죄를 결정하고 파면이 선고됩니다. 하루아침에 모두를 설득한 것이 아닙니다. 문서 하나씩 기록을 쌓아 더는 외면할 수 없는 사건을 만들었습니다.",
    "Public support falls below the floor. Members start avoiding the cameras. The articles are tabled indefinitely, and the whole thing becomes a cautionary tale told at staff retreats.": "국민 지지가 바닥납니다. 의원들은 카메라를 피합니다. 탄핵안은 무기한 보류되고 사건은 보좌진 연수에서 전하는 경고담이 됩니다.",
