    "Support on success: {0} to {1}": "תמיכה בהצלחה: {0} עד {1}",
    "On failure: {0} −{1}–{2}; support −{3}–{4}.": "בכישלון: {0} פחות {1}–{2}; תמיכה פחות {3}–{4}.",
    "Evidence cost on success: {0}.": "עלות ראיות בהצלחה: {0}.",
    "No affordable moves. Adjourn to rebuild capital; blowback can halve the recovery.": "אין מהלכים שניתן לממן. נעלו את הישיבה לשיקום ההון; תגובת נגד עלולה לחצות אותו.",
    "BLOWBACK — Political capital halved: {0} → {1} (rounded down).": "תגובת נגד — ההון הפוליטי נחצה: {0} ← {1} (עיגול מטה).",
    "Extended Toolkit unlocked: 56 moves per phase instead of 28.": "כלים מורחבים: 56 מהלכים בכל שלב במקום 28.",
    "A shorter term. Less public fatigue. 28 moves per phase.": "כהונה קצרה יותר, פחות שחיקה ציבורית. 28 מהלכים בכל שלב.",
    "A longer term. More public fatigue. 56 moves per phase, with lower success odds.": "כהונה ארוכה יותר, שחיקה רבה יותר. 56 מהלכים בכל שלב, עם סיכויי הצלחה נמוכים יותר.",
    "Adjourn skips unused days to recover capital. Every blowback halves your capital after recovery, rounded down.": "נעילת הישיבה מדלגת על הימים שנותרו כדי לשקם הון. כל תגובת נגד חוצה את ההון לאחר ההתאוששות, בעיגול מטה.",
    "Every move can fail. Cards show success odds and rewards; stronger public support improves your odds.": "כל מהלך עלול להיכשל. הקלפים מציגים סיכויים ותגמולים; תמיכה גבוהה יותר משפרת את הסיכוי.",
    "Public support shifts after every move and active-play day. Paused time does not affect it.": "התמיכה משתנה אחרי כל מהלך ויום משחק פעיל. זמן בהשהיה לא משפיע."
