    "the Family Foundation Filing": "家族基金会申报案",
    "the Midnight Regulatory Rollback": "午夜撤销监管案",
    "The hearing room is standing room only.": "听证室座无虚席，只能站着旁听。",
    "Three networks cut away from regular programming.": "三家电视台中断常规节目。",
    "The press gallery is unusually quiet.": "记者席异常安静。",
    "Someone leaks the witness list at 11:58 PM.": "有人在23:58泄露证人名单。",
    "A court clerk hands over a sealed envelope.": "法庭书记员递来密封信封。",
    "The ranking member calls it \"the paper trail of the century.\"": "资深委员称之为“世纪文件线索”。",
