    "No blowback this turn. The administration fails to land a counterattack.": "本回合没有反击。政府未能发动有效回击。",
    "You never assembled enough evidence to report articles out of committee. The term ended with the boxes still unopened.": "未能收集足够证据，将条款移出委员会。任期结束时，箱子仍未打开。",
    "The vote count stalled short of 218. The articles die on the calendar.": "票数未达218。条款随期限届满而失效。",
    "The Senate never reaches 67. The President is acquitted, declares victory, and fundraises off it.": "参议院未达67票。总统获判无罪，宣布胜利并借机募款。",
    "THE TERM ENDS": "任期结束",
    "THE CASE COLLAPSES": "案件崩溃",
    "Extended Toolkit unlocked: 14 moves per phase instead of 7.": "扩展工具已解锁：每阶段14项行动，而非7项。",
    "The calendar is live: 12 seconds of active play costs one session day. Moves also spend their listed days.": "日程正在推进：每12秒有效游玩消耗一天。行动也会消耗标注天数。",
    "The House will come to order…": "现在开会……",
    "Select a mode above to enable Start. The clock is stopped.": "选择模式以启用开始按钮。计时器已停止。",
    "The Senate votes to convict. The Chief Justice administers the oath of removal. You did not change anyone's mind in a single afternoon — you built a record, one document at a time, until the record became impossible to ignore.": "参议院投票定罪，罢免正式生效。你并非在一个下午改变所有人的想法，而是一份份积累文件，直到证据再也无法被忽视。",
    "Public support falls below the floor. Members start avoiding the cameras. The articles are tabled indefinitely, and the whole thing becomes a cautionary tale told at staff retreats.": "公众支持跌破底线，议员开始躲避镜头。条款被无限期搁置，整个事件成了工作人员培训时的反面教材。",
