    "Apply pressure for a larger but less reliable gain.": "施加压力，争取更大但更不稳定的收益。",
    "A high-risk play with a large upside and downside.": "高风险行动，收益与损失都很大。",
    "Trade public goodwill for a better chance of progress.": "牺牲公众好感，换取更高的推进机会。",
    "Succeeded": "成功",
    "Setback": "受挫",
    "{0}: {1}. {2} {3}; support {4}.": "{0}：{1}。{2} {3}；支持{4}。",
    "PUBLIC OPINION — Support {0}% → {1}%.": "公众意见 — 支持{0}% → {1}%。",
    "Last shift: {0}": "最近变化：{0}",
    "Success: {0}% · {1} +{2}–{3}": "成功率：{0}% · {1} +{2}–{3}",
    "Support on success: {0} to {1}": "成功时支持：{0}至{1}",
    "On failure: {0} −{1}–{2}; support −{3}–{4}.": "失败时：{0}减少{1}–{2}；支持减少{3}–{4}。",
    "Evidence cost on success: {0}.": "成功时消耗证据：{0}。",
    "No affordable moves. Adjourn to rebuild capital; blowback can halve the recovery.": "资源不足，无法行动。休会以恢复资本；反击可能使恢复后的资本减半。",
    "BLOWBACK — Political capital halved: {0} → {1} (rounded down).": "反击 — 政治资本减半：{0} → {1}（向下取整）。",
    "Extended Toolkit unlocked: 56 moves per phase instead of 28.": "扩展工具：每阶段56项行动，而非28项。",
    "A shorter term. Less public fatigue. 28 moves per phase.": "任期较短，公众疲劳较少。每阶段28项行动。",
    "A longer term. More public fatigue. 56 moves per phase, with lower success odds.": "任期较长，公众疲劳更多。每阶段56项行动，成功率更低。",
    "Adjourn skips unused days to recover capital. Every blowback halves your capital after recovery, rounded down.": "休会会跳过剩余天数以恢复资本。每次反击都将恢复后的资本减半，并向下取整。",
    "Every move can fail. Cards show success odds and rewards; stronger public support improves your odds.": "任何行动都可能失败。卡片显示成功率与回报；公众支持越高，成功率越高。",
    "Public support shifts after every move and active-play day. Paused time does not affect it.": "每次行动和每个有效游玩日后，公众支持都会波动。暂停时间不会影响支持。"
