    "Political fiction: every president, scandal, witness and senator is invented. The game simplifies U.S. constitutional procedures.": "政治フィクションです。大統領、疑惑、証人、上院議員はすべて架空です。ゲームは米国の憲法上の手続きを簡略化しています。",
    "Call the House to Order": "下院の開会を宣言しよう",
