    "24 months · 240 session days": "24か月 · 審議日240日",
    "A shorter term. Less public fatigue. Seven moves per phase.": "短い任期、少ない世論の疲労。各段階に7つの行動。",
    "Monthly: 20–26 capital · support −1 (+fatigue) · 65% blowback risk": "毎月：資本+20〜26 · 支持−1（疲労分を加算）· 反撃の確率65%",
