    "48 months · 480 session days": "48か月 · 審議日480日",
    "A longer term. More public fatigue. Fourteen moves per phase.": "長い任期、大きな世論の疲労。各段階に14の行動。",
    "Monthly: 16–22 capital · support −2 (+fatigue) · evidence −2 after investigation · 80% blowback risk": "毎月：資本+16〜22 · 支持−2（疲労分を加算）· 調査後は証拠−2 · 反撃の確率80%",
    "Quickstart · Your path to a verdict": "クイックスタート · 評決への道",
    "Build 75 Evidence to bring articles to the House.": "証拠を75集め、弾劾条項を下院本会議に提出します。",
    "Win 218 House votes to impeach, then 67 Senate votes to convict and remove.": "下院で218票を集めて弾劾訴追し、上院で67票を集めて有罪・罷免を目指します。",
    "Spend capital and days on moves. Every 12 seconds of active play also spends one day; 10 days make a month.": "行動には資本と日数が必要です。実際のプレイ時間12秒ごとにも1日を消費します。10日で1か月が進みます。",
    "Adjourn skips unused days. Each month restores capital but brings fatigue and a chance of blowback.": "散会すると残りの日を飛ばします。毎月資本が回復しますが、世論が疲れ、反撃を受ける可能性もあります。",
    "Finish before the term ends. Keep support at 12% or higher at each monthly review. Pause or hide the tab to stop the clock.": "任期中に目標を達成しましょう。毎月の判定時に支持率12%以上を維持してください。一時停止やタブを隠すことで時計を止められます。",
