    "{0} new items secured — but the contempt fight dominates the news and costs you five points.": "証拠{0}件を確保。ただし議会侮辱を巡る争いが報道を独占し、支持を5失いました。",
    "The Chief of Staff testifies for seven hours. {0} new evidentiary items.": "首席補佐官が7時間証言。新たな証拠{0}件。",
