    "The outside accountant follows the money through three shell entities. {0} new items.": "外部会計士が3つのペーパーカンパニーの資金を追跡。証拠{0}件を入手。",
    "Two foreign ministries comply. {0} new items, and a very good photograph of a courier van.": "外国の2省庁が協力。証拠{0}件と、配送車の見事な写真を入手。",
