    "CLOCK — A session day expires. Days remaining this month: {0}.": "時計 — 審議日が1日経過。今月の残り日数：{0}。",
    "🏛️ Evidence threshold of {0} met. Articles reported to the floor. You begin with {1} committed votes.": "🏛️ 証拠{0}の基準に到達。条項を本会議へ提出。確約済みの{1}票で開始します。",
    "⚖️ The House votes to impeach. The Senate trial begins. You begin with {0} votes in the chamber.": "⚖️ 下院が弾劾訴追を可決。上院での審理を{0}票から開始します。",
