    "12 seconds = 1 session day": "12秒 = 審議日1日",
    "Campaign ended · clock stopped": "キャンペーン終了 · 時計停止",
    "The clock starts when you press Start the Session": "「審議を開始」を押すと時計が動きます",
    "Paused · no calendar time lost": "一時停止中 · 時間は失われません",
    "Paused while this tab is hidden": "タブが隠れている間は一時停止",
    "Paused while a dialog is open": "ダイアログ表示中は一時停止",
    "CONVICTED": "有罪",
    "BLOWBACK": "反撃",
    "BREAKTHROUGH": "突破口",
    "No blowback this turn. The administration fails to land a counterattack.": "今ターンは反撃なし。政権は反攻に失敗しました。",
    "You never assembled enough evidence to report articles out of committee. The term ended with the boxes still unopened.": "委員会から条項を出すだけの証拠を集められませんでした。箱も開かないまま任期が終わりました。",
    "The vote count stalled short of 218. The articles die on the calendar.": "票数は218に届かず。期限切れで条項は廃案となりました。",
    "The Senate never reaches 67. The President is acquitted, declares victory, and fundraises off it.": "上院は67票に届かず。大統領は無罪となり、勝利を宣言して資金集めに利用します。",
    "THE TERM ENDS": "任期終了",
    "THE CASE COLLAPSES": "事件が崩壊",
    "Extended Toolkit unlocked: 14 moves per phase instead of 7.": "拡張ツール解放：各段階で7つの代わりに14の行動。",
    "The calendar is live: 12 seconds of active play costs one session day. Moves also spend their listed days.": "時計が動いています。実際のプレイ12秒ごとに審議日1日を消費。行動も表示された日数を消費します。",
    "The House will come to order…": "これより開会します…",
    "Select a mode above to enable Start. The clock is stopped.": "上のモードを選ぶと開始できます。時計は止まっています。",
    "The Senate votes to convict. The Chief Justice administers the oath of removal. You did not change anyone's mind in a single afternoon — you built a record, one document at a time, until the record became impossible to ignore.": "上院が有罪を可決し、罷免が宣告されます。たった一日ですべての考えを変えたのではありません。文書を一つずつ積み重ね、ついに無視できない記録を作り上げたのです。",
    "Public support falls below the floor. Members start avoiding the cameras. The articles are tabled indefinitely, and the whole thing becomes a cautionary tale told at staff retreats.": "世論の支持が底を割りました。議員たちはカメラを避け、条項は無期限に棚上げ。事件は職員研修で語られる戒めの話になりました。",
